const item = $input.first().json;

// ============================================================
// AEGIS — PARSE ANALYST OUTPUT
// ============================================================

const raw =
  item.output ??
  item.text ??
  item.response ??
  "";

if (!raw || typeof raw !== "string") {
  throw new Error(
    "Parse Analyst Output: no Analyst output found."
  );
}

// ============================================================
// CLEAN MODEL RESPONSE
// ============================================================

let cleaned = raw.trim();

// Remove markdown fences if the model ignored the contract.
cleaned = cleaned
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Remove accidental leading text before the first JSON object.
const start = cleaned.indexOf("{");

if (start === -1) {
  throw new Error(
    "Parse Analyst Output: Analyst returned no JSON object."
  );
}

cleaned = cleaned.slice(start);

// ============================================================
// FIND COMPLETE JSON OBJECT
// ============================================================

function extractBalancedObject(text) {
  let depth = 0;
  let inString = false;
  let escaped = false;
  let started = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === "\\" && inString) {
      escaped = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (inString) {
      continue;
    }

    if (char === "{") {
      depth++;
      started = true;
    }

    if (char === "}") {
      depth--;

      if (started && depth === 0) {
        return text.slice(0, i + 1);
      }
    }
  }

  return null;
}

let candidate = extractBalancedObject(cleaned);

if (!candidate) {
  throw new Error(
    "Parse Analyst Output: incomplete JSON object returned by Analyst."
  );
}

// ============================================================
// PARSE JSON
// ============================================================

let parsed;

try {
  parsed = JSON.parse(candidate);
} catch (error) {

  // Try removing trailing commas only.
  const repaired = candidate.replace(
    /,\s*([}\]])/g,
    "$1"
  );

  try {
    parsed = JSON.parse(repaired);
  } catch (secondError) {
    throw new Error(
      "Parse Analyst Output: Analyst returned invalid JSON.\n" +
      secondError.message +
      "\n\nRaw Analyst output:\n" +
      raw
    );
  }
}

// ============================================================
// NORMALIZE ANALYSIS
// ============================================================

// Re-analysis may return the analysis directly.
// Normal Analyst output also returns the analysis directly.

const analysis =
  parsed.analysis &&
  typeof parsed.analysis === "object"
    ? parsed.analysis
    : parsed;

// ============================================================
