  "observed_facts",
  "evidence_analysis",
  "hypotheses",
  "missing_evidence",
  "recommended_next_steps",
  "overall_confidence"
];

for (const field of requiredFields) {
  if (!(field in analysis)) {
    throw new Error(
      `Parse Analyst Output: missing required field "${field}".`
    );
  }
}

// ============================================================
// NORMALIZE LOOP STATE
// ============================================================

const currentIteration =
  Number(item.aegis_iteration ?? 0);

// ============================================================
// RETURN AEGIS STATE
// ============================================================

return [
  {
    json: {

      // --------------------------------------------------------
      // AUTHORITATIVE ANALYSIS
      // --------------------------------------------------------

      ...analysis,

      analysis,

      // --------------------------------------------------------
      // LOOP STATE
      // --------------------------------------------------------

      aegis_iteration: currentIteration,

      max_iterations:
        Number(item.max_iterations ?? 3),

      // --------------------------------------------------------
      // REANALYSIS STATE
      // --------------------------------------------------------

      previous_analysis:
        item.previous_analysis ?? null,

      feedback:
        item.feedback ?? null,

      reanalysis_required:
        item.reanalysis_required ?? false
    }
