];

// ============================================================
// AEGIS — Deterministic Evidence Metrics
// ============================================================

// Current input = output of Collect Sales Evidence
const current = $input.first().json;

// Original event = output of Generate Business Event
const generatedEvent = $("Generate Business Event").first().json;


// ============================================================
// Recursive field finder
// ============================================================

function findField(obj, targetKey, path = "") {
  if (obj === null || obj === undefined) {
    return null;
  }

  if (typeof obj !== "object") {
    return null;
  }

  if (Object.prototype.hasOwnProperty.call(obj, targetKey)) {
    return {
      value: obj[targetKey],
      path: path ? `${path}.${targetKey}` : targetKey
    };
  }

  for (const key of Object.keys(obj)) {
    const result = findField(
      obj[key],
      targetKey,
      path ? `${path}.${key}` : key
    );

    if (result !== null) {
      return result;
    }
  }

  return null;
}


function findRequired(obj, key, sourceName) {
  const result = findField(obj, key);

  if (!result) {
    throw new Error(
      `Could not find "${key}" in ${sourceName}.`
    );
  }

  return result;
}


// ============================================================
// Revenue comes from Generate Business Event
// ============================================================

const previousRevenueResult =
  findRequired(
    generatedEvent,
    "previous_revenue",
    "Generate Business Event"
  );

const currentRevenueResult =
  findRequired(
    generatedEvent,
    "current_revenue",
    "Generate Business Event"
  );


// ============================================================
// Payment/support evidence
//
// Search both:
// 1. Collect Sales Evidence
// 2. Generate Business Event
//
// This makes the node tolerant of our current data structure.
// ============================================================

function findFromSources(key, sources) {

  for (const source of sources) {

    const result = findField(
      source.object,
      key
    );

    if (result !== null) {
      return {
        ...result,
        source: source.name
      };
    }
  }

  throw new Error(
    `Could not find "${key}" in any available source.`
  );
}


const sources = [
  {
    name: "Collect Sales Evidence",
    object: current
  },
  {
    name: "Generate Business Event",
    object: generatedEvent
  }
];


const previousPaymentFailuresResult =
  findFromSources(
    "previous_failure_count",
    sources
  );

const currentPaymentFailuresResult =
  findFromSources(
    "current_failure_count",
    sources
  );

const previousPaymentTicketsResult =
  findFromSources(
    "previous_payment_tickets",
    sources
  );

const currentPaymentTicketsResult =
  findFromSources(
    "current_payment_tickets",
    sources
  );


// ============================================================
// Convert values to numbers
// ============================================================

const previousRevenue =
  Number(previousRevenueResult.value);

const currentRevenue =
  Number(currentRevenueResult.value);

const previousPaymentFailures =
  Number(previousPaymentFailuresResult.value);

const currentPaymentFailures =
  Number(currentPaymentFailuresResult.value);

const previousPaymentTickets =
  Number(previousPaymentTicketsResult.value);

const currentPaymentTickets =
  Number(currentPaymentTicketsResult.value);


// ============================================================
// Validate
// ============================================================

const values = {
  previousRevenue,
  currentRevenue,
  previousPaymentFailures,
  currentPaymentFailures,
  previousPaymentTickets,
  currentPaymentTickets
};

for (const [name, value] of Object.entries(values)) {

  if (!Number.isFinite(value)) {

    throw new Error(
      `${name} is not a valid number: ${value}`
    );

  }

}


// ============================================================
// Deterministic percentage calculation
// ============================================================

function percentageChange(previous, current) {

  if (previous === 0) {
    return null;
  }

  return Number(
    (
      ((current - previous) / previous) * 100
    ).toFixed(2)
  );

}


// ============================================================
// Calculate
// ============================================================

const revenueChange =
  percentageChange(
    previousRevenue,
    currentRevenue
  );

const paymentFailureChange =
  percentageChange(
    previousPaymentFailures,
    currentPaymentFailures
  );

const paymentTicketChange =
  percentageChange(
    previousPaymentTickets,
    currentPaymentTickets
  );


// ============================================================
// Return
// ============================================================

return [
  {
    json: {

      ...current,

      metrics: {

        revenue: {
          previous: previousRevenue,
          current: currentRevenue,
          percentage_change: revenueChange,

          direction:
            currentRevenue > previousRevenue
              ? "increased"
              : currentRevenue < previousRevenue
              ? "decreased"
              : "unchanged"
        },


        payment_failures: {
          previous: previousPaymentFailures,
          current: currentPaymentFailures,
          percentage_change: paymentFailureChange,

          direction:
            currentPaymentFailures > previousPaymentFailures
              ? "increased"
              : currentPaymentFailures < previousPaymentFailures
              ? "decreased"
              : "unchanged"
        },


        payment_tickets: {
          previous: previousPaymentTickets,
          current: currentPaymentTickets,
          percentage_change: paymentTicketChange,

          direction:
            currentPaymentTickets > previousPaymentTickets
              ? "increased"
              : currentPaymentTickets < previousPaymentTickets
              ? "decreased"
              : "unchanged"
        }

      },


      metric_sources: {

        previous_revenue:
          `Generate Business Event → ${previousRevenueResult.path}`,

        current_revenue:
          `Generate Business Event → ${currentRevenueResult.path}`,

        previous_payment_failures:
          `${previousPaymentFailuresResult.source} → ${previousPaymentFailuresResult.path}`,

        current_payment_failures:
          `${currentPaymentFailuresResult.source} → ${currentPaymentFailuresResult.path}`,

        previous_payment_tickets:
          `${previousPaymentTicketsResult.source} → ${previousPaymentTicketsResult.path}`,

        current_payment_tickets:
          `${currentPaymentTicketsResult.source} → ${currentPaymentTicketsResult.path}`

      },


      metrics_status: "calculated"

    }
  }
];

const item = $input.first().json;

let raw = item.output;

if (typeof raw !== "string") {
  throw new Error(
    "Parse Critic Output: Aegis Critic output is not a string."
  );
}

raw = raw.trim();

// ============================================================
// REMOVE MARKDOWN CODE FENCES
// ============================================================

raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// ============================================================
// TRY DIRECT JSON
// ============================================================

let critic;

try {
  critic = JSON.parse(raw);
} catch (directError) {

  // ==========================================================
  // FALLBACK: EXTRACT JSON OBJECT
  // ==========================================================

  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");

  if (
    firstBrace === -1 ||
    lastBrace === -1 ||
    lastBrace <= firstBrace
  ) {
    throw new Error(
      `Parse Critic Output: No JSON object found.\n\n` +
      `Raw output:\n${raw}`
    );
  }

  const jsonCandidate = raw.slice(
    firstBrace,
    lastBrace + 1
  );

  try {
    critic = JSON.parse(jsonCandidate);
  } catch (extractError) {
    throw new Error(
      `Parse Critic Output: Invalid JSON after extraction.\n\n` +
      `Raw output:\n${raw}\n\n` +
      `Parser error:\n${extractError.message}`
    );
  }
}

// ============================================================
// HANDLE POSSIBLE WRAPPER
// ============================================================

// If the Critic returns:
//
// {
//   "critic": {
//      ...
//   }
// }
//
// unwrap it.

if (
  critic &&
  typeof critic.critic === "object" &&
  critic.critic !== null
) {
  critic = critic.critic;
}

// ============================================================
// VALIDATION
// ============================================================

if (!critic || typeof critic !== "object") {
  throw new Error(
    "Parse Critic Output: Parsed result is not a valid critic object."
  );
}

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      ...item,
      critic
    }
  }
];

const item = $input.first().json;

const critic = item.critic;

if (!critic) {
  throw new Error("Decision Gate: critic object not found.");
}

const iteration = Number(item.aegis_iteration ?? 0);
const maxIterations = Number(item.max_iterations ?? 3);

const analystScore = Number(critic.analyst_score ?? 0);
const criticConfidence = Number(critic.critic_confidence ?? 0);

const numericalErrors = Array.isArray(critic.numerical_errors)
  ? critic.numerical_errors.length
  : 0;

const unsupportedClaims = Array.isArray(critic.unsupported_claims)
  ? critic.unsupported_claims.length
  : 0;

const requiredCorrections = Array.isArray(critic.required_corrections)
  ? critic.required_corrections.length
  : 0;

const scorePass = analystScore >= 0.75;
const confidencePass = criticConfidence >= 0.70;
const numericalPass = numericalErrors === 0;
const unsupportedPass = unsupportedClaims === 0;
const correctionsPass = requiredCorrections === 0;

const passed =
  scorePass &&
  confidencePass &&
  numericalPass &&
  unsupportedPass &&
  correctionsPass;

const maxIterationsReached = iteration >= maxIterations;

let status;
let route;

if (passed) {
  status = "PASS";
  route = "ACTION";
} else if (maxIterationsReached) {
  status = "INCONCLUSIVE";
  route = "STOP";
} else {
  status = "FAIL";
  route = "RE_ANALYZE";
}

return [
  {
    json: {
      ...item,

      decision: {
        status,
        route,

        reasons: {
          scorePass,
          confidencePass,
          numericalPass,
          unsupportedPass,
          correctionsPass,
          maxIterationsReached
        },

        thresholds: {
          minimum_analyst_score: 0.75,
          minimum_critic_confidence: 0.70
        }
      },

      aegis_iteration: iteration,
      max_iterations: maxIterations
    }
  }
];

const item = $input.first().json;

// ------------------------------------------------------------
// CRITIC
// ------------------------------------------------------------

const critic = item.critic;

if (!critic) {
  throw new Error(
    "Build Critic Feedback: critic object not found."
  );
}

// ------------------------------------------------------------
// RECOVER THE ANALYST'S LATEST ANALYSIS
// ------------------------------------------------------------

// First try the incoming item.
let previousAnalysis = item.analysis ?? null;

// If Parse Critic Output dropped it, retrieve it directly
// from the latest Parse Analyst Output execution.
if (!previousAnalysis) {
  try {
    previousAnalysis = $('Parse Analyst Output').first().json.analysis;
  } catch (error) {
    throw new Error(
      "Build Critic Feedback: Could not retrieve the Analyst analysis from Parse Analyst Output."
    );
  }
}

if (!previousAnalysis) {
  throw new Error(
    "Build Critic Feedback: Analyst analysis is unavailable."
  );
}

// ------------------------------------------------------------
// BUILD FEEDBACK
// ------------------------------------------------------------

const feedback = {
  verdict: critic.critic_verdict ?? "unknown",

  analyst_score: Number(critic.analyst_score ?? 0),

  critic_confidence: Number(critic.critic_confidence ?? 0),

  factual_errors: Array.isArray(critic.factual_errors)
    ? critic.factual_errors
    : [],

  numerical_errors: Array.isArray(critic.numerical_errors)
    ? critic.numerical_errors
    : [],

  unsupported_claims: Array.isArray(critic.unsupported_claims)
    ? critic.unsupported_claims
    : [],

  evidence_gaps: Array.isArray(critic.evidence_gaps)
    ? critic.evidence_gaps
    : [],

  hypothesis_assessment: Array.isArray(critic.hypothesis_assessment)
    ? critic.hypothesis_assessment
    : [],

  alternative_explanations: Array.isArray(critic.alternative_explanations)
    ? critic.alternative_explanations
    : [],

  required_corrections: Array.isArray(critic.required_corrections)
    ? critic.required_corrections
    : []
};

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      ...item,

      previous_analysis: previousAnalysis,

      feedback,

      reanalysis_required: true
    }
  }
];

