function extractJson(text) {

  // 1. Remove markdown code fences
  let cleaned = text
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // 2. First try the entire response
  try {
    return JSON.parse(cleaned);
  } catch {}

  // 3. Try extracting the largest JSON object
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1 || end <= start) {
    throw new Error(
      "AI Analyst returned no JSON object."
    );
  }

  let candidate =
    cleaned.slice(start, end + 1).trim();

  // 4. Remove JavaScript-style comments
  candidate = candidate
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");

  // 5. Try again
  try {
    return JSON.parse(candidate);
  } catch (error) {
    throw new Error(
      "AI Analyst returned invalid JSON after extraction: " +
      error.message
    );
  }
}

